import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { uploadJob } from "../api";

export default function Jobs() {
  const [jdText, setJdText] = useState("");
  const [jdFile, setJdFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [jdUploaded, setJdUploaded] = useState(false);

  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();

    const formData = new FormData();

    if (jdFile) {
      formData.append("jd_file", jdFile);
    } else {
      formData.append("jd_text", jdText);
    }

    try {
      setLoading(true);
      setMessage("");

      await uploadJob(formData);

      setMessage("Job Description uploaded successfully");
      setJdUploaded(true);
    } catch (err) {
      setMessage("Failed to upload Job Description");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="page">
      <div className="container">
        <h2>Add Job Description</h2>
        <p>Upload a JD file or paste the job description text.</p>

        <div className="card">
          <form onSubmit={handleSubmit}>
            <label>Job Description Text</label>
            <textarea
              placeholder="Paste job description here (optional)"
              value={jdText}
              onChange={(e) => setJdText(e.target.value)}
            />

            <label>Upload JD File (PDF / DOCX)</label>
            <input
              type="file"
              accept=".pdf,.docx"
              onChange={(e) => setJdFile(e.target.files[0])}
            />

            <button type="submit" disabled={loading}>
              {loading ? "Uploading..." : "Upload JD"}
            </button>

            {message && <p style={{ marginTop: "12px" }}>{message}</p>}

            {jdUploaded && (
              <div style={{ marginTop: "20px" }}>
                <button type="button" onClick={() => navigate("/resumes")}>
                  Add Resumes →
                </button>
              </div>
            )}
          </form>
        </div>
      </div>
    </div>
  );
}
